import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";

const { lookupMock } = vi.hoisted(() => ({ lookupMock: vi.fn() }));

vi.mock("node:dns", () => ({
  promises: { lookup: lookupMock },
}));

const { triggerDeployHook } = await import("./deploy-hook");

// A documentation-range address (RFC 5737) — not reserved by any rule under
// test, so it stands in for "some public host" without being a real one.
const PUBLIC_ADDRESS = { address: "203.0.113.10", family: 4 };

describe("triggerDeployHook", () => {
  beforeEach(() => {
    vi.stubGlobal("fetch", vi.fn());
    lookupMock.mockReset();
    lookupMock.mockResolvedValue([PUBLIC_ADDRESS]);
  });

  afterEach(() => {
    vi.unstubAllGlobals();
    vi.restoreAllMocks();
  });

  it("succeeds on the first attempt", async () => {
    vi.mocked(fetch).mockResolvedValue(new Response(null, { status: 200 }));

    const result = await triggerDeployHook("acme", "https://hooks.example.invalid/deploy/acme");

    expect(result).toEqual({ ok: true, attempts: 1 });
    expect(fetch).toHaveBeenCalledTimes(1);
    expect(fetch).toHaveBeenCalledWith(
      "https://hooks.example.invalid/deploy/acme",
      expect.objectContaining({ method: "POST", redirect: "manual" }),
    );
  });

  it("retries once after a network failure and then succeeds", async () => {
    vi.mocked(fetch)
      .mockRejectedValueOnce(new Error("network down"))
      .mockResolvedValueOnce(new Response(null, { status: 200 }));

    const result = await triggerDeployHook("acme", "https://hooks.example.invalid/deploy/acme");

    expect(result).toEqual({ ok: true, attempts: 2 });
  });

  it("treats a non-2xx response as a failure worth retrying", async () => {
    vi.mocked(fetch)
      .mockResolvedValueOnce(new Response(null, { status: 503 }))
      .mockResolvedValueOnce(new Response(null, { status: 200 }));

    const result = await triggerDeployHook("acme", "https://hooks.example.invalid/deploy/acme");

    expect(result.ok).toBe(true);
    expect(fetch).toHaveBeenCalledTimes(2);
  });

  it("gives up after exhausting every retry", async () => {
    vi.mocked(fetch).mockRejectedValue(new Error("network down"));

    const result = await triggerDeployHook("acme", "https://hooks.example.invalid/deploy/acme");

    expect(result.ok).toBe(false);
    expect(result.attempts).toBe(3);
    expect(fetch).toHaveBeenCalledTimes(3);
  });

  describe("rejects a URL that isn't safe to fetch, without ever calling fetch", () => {
    it.each([
      ["a non-https URL", "http://hooks.example.invalid/deploy/acme"],
      ["a non-URL string", "not a url"],
      ["a file URL", "file:///etc/passwd"],
      ["a literal localhost hostname", "https://localhost/deploy/acme"],
      ["an *.internal hostname", "https://deploy.corp.internal/deploy/acme"],
    ])("rejects %s", async (_description, url) => {
      const result = await triggerDeployHook("acme", url);

      expect(result).toEqual({ ok: false, attempts: 0 });
      expect(fetch).not.toHaveBeenCalled();
    });

    it("rejects a hostname that resolves to a loopback address", async () => {
      lookupMock.mockResolvedValue([{ address: "127.0.0.1", family: 4 }]);

      const result = await triggerDeployHook("acme", "https://hooks.example.invalid/deploy/acme");

      expect(result).toEqual({ ok: false, attempts: 0 });
      expect(fetch).not.toHaveBeenCalled();
    });

    it("rejects a hostname that resolves to the cloud metadata address", async () => {
      lookupMock.mockResolvedValue([{ address: "169.254.169.254", family: 4 }]);

      const result = await triggerDeployHook("acme", "https://hooks.example.invalid/deploy/acme");

      expect(result).toEqual({ ok: false, attempts: 0 });
      expect(fetch).not.toHaveBeenCalled();
    });

    it("rejects a hostname that resolves to a private-network address", async () => {
      lookupMock.mockResolvedValue([{ address: "10.1.2.3", family: 4 }]);

      const result = await triggerDeployHook("acme", "https://hooks.example.invalid/deploy/acme");

      expect(result).toEqual({ ok: false, attempts: 0 });
      expect(fetch).not.toHaveBeenCalled();
    });

    it("rejects a hostname where only one of several resolved addresses is reserved", async () => {
      lookupMock.mockResolvedValue([PUBLIC_ADDRESS, { address: "192.168.1.1", family: 4 }]);

      const result = await triggerDeployHook("acme", "https://hooks.example.invalid/deploy/acme");

      expect(result).toEqual({ ok: false, attempts: 0 });
      expect(fetch).not.toHaveBeenCalled();
    });

    it("rejects an IPv6 loopback address", async () => {
      lookupMock.mockResolvedValue([{ address: "::1", family: 6 }]);

      const result = await triggerDeployHook("acme", "https://hooks.example.invalid/deploy/acme");

      expect(result).toEqual({ ok: false, attempts: 0 });
      expect(fetch).not.toHaveBeenCalled();
    });

    it("rejects an IPv6 unique-local address", async () => {
      lookupMock.mockResolvedValue([{ address: "fd00:ec2::254", family: 6 }]);

      const result = await triggerDeployHook("acme", "https://hooks.example.invalid/deploy/acme");

      expect(result).toEqual({ ok: false, attempts: 0 });
      expect(fetch).not.toHaveBeenCalled();
    });

    it("rejects an IPv4-mapped IPv6 address whose embedded address is reserved", async () => {
      lookupMock.mockResolvedValue([{ address: "::ffff:169.254.169.254", family: 6 }]);

      const result = await triggerDeployHook("acme", "https://hooks.example.invalid/deploy/acme");

      expect(result).toEqual({ ok: false, attempts: 0 });
      expect(fetch).not.toHaveBeenCalled();
    });

    it("rejects a hostname that fails to resolve", async () => {
      lookupMock.mockRejectedValue(new Error("ENOTFOUND"));

      const result = await triggerDeployHook("acme", "https://hooks.example.invalid/deploy/acme");

      expect(result).toEqual({ ok: false, attempts: 0 });
      expect(fetch).not.toHaveBeenCalled();
    });
  });
});

